const
    MAXSIZE=20;
type
    INTARR=array [1..MAXSIZE,1..MAXSIZE] of integer;
Procedure TRANSPOSE (var A: INTARR; N : integer);
var
    I, J, TMP: integer;
begin
    for I:=1 to N – 1 do
    for J:=1 to N do
    begin
        TMP:= A[I, J];
        A[I, J]:= A[J, I];
        A[J, I]:= TMP
    end
end;

